'use client';
import * as React from 'react';
import { Badge, Button, Card, DescriptionList, Empty, Evidence, Heading, Icon, Metric, Modal, Money, Notice, Progress, Search, type IconName } from './components';
import { attentionFor, createDesignExtra, emptyDraft, jobs, personas, pounds, restoreDesign, seedExtras, statusLabels, totalPence, transition, validateDraft, type DesignAction, type Draft, type Extra, type Persona } from './model';
import { groups, screens, states, type Screen } from './catalog';
import { PracticeWorkspace } from './connected';
import type { NorthsideClient } from './practice';

type Page = 'today'|'jobs'|'job'|'capture'|'extras'|'review'|'detail'|'possible'|'billing'|'statements'|'reports'|'setup'|'quotes'|'supplies'|'money'|'final'|'catalogue'|'screen'|'states'|'help';
type ActionDialog={kind:DesignAction|'reset';extra?:Extra};
type State={persona:Persona;page:Page;mode:'design'|'practice';extras:Extra[];selected:string;job:string;draft:Draft;errors:Record<string,string>;query:string;filter:string;message:string;storage:string;dialog:ActionDialog|null;dialogText:string;amount:string;screen:string;stateIndex:number;navigationOpen:boolean;quoteSent:boolean;quoteNote:string;finalLocked:boolean;finalCompleted:boolean;catalogueGroup:number};
const STORAGE='jobguard-design-extras.v1';
const pageTitles:Record<Page,string>={today:'Today',jobs:'Jobs',job:'Work order',capture:'Log an extra',extras:'My extras',review:'Review queue',detail:'Extra detail',possible:'Possible extras',billing:'Billing',statements:'Statements',reports:'Reports',setup:'Settings',quotes:'Quotes',supplies:'Supplies',money:'Money',final:'Final account',catalogue:'Screen catalogue',screen:'Screen specimen',states:'Interface states',help:'Help'};
const navFor=(persona:Persona):[Page,IconName,string][]=>persona==='operative'?[['today','home','Today'],['jobs','jobs','Jobs'],['extras','layers','My extras']]:persona==='client'?[['review','file','My requests']]:persona==='builder'?[['today','home','Today'],['jobs','jobs','Jobs'],['quotes','file','Quotes'],['money','money','Money'],['supplies','layers','Supplies']]:persona==='finance'?[['today','home','Overview'],['jobs','jobs','Work orders'],['review','check','Approvals'],['billing','money','Billing'],['statements','file','Statements'],['reports','grid','Reports'],['setup','settings','Setup']]:[['today','home','Overview'],['review','check','Review queue'],['jobs','jobs','Work orders'],['possible','search','Possible extras']];
function toneFor(e:Extra):'amber'|'green'|'red'|'blue'{return e.state==='approved'?'green':['rejected','withdrawn'].includes(e.state)?'red':e.state==='logged'?'amber':'blue';}
const showRows=(items:Extra[],q:string,filter:string)=>items.filter(e=>(filter==='all'||e.state===filter)&&`${e.id} ${e.description} ${e.job}`.toLowerCase().includes(q.toLowerCase()));
/** This controller owns fictional UI state only. Practice mode is a separately mounted client. */
export class PreviewApp extends React.Component<{createPracticeClient?:()=>NorthsideClient},State>{
  state:State={persona:'operative',page:'today',mode:'design',extras:seedExtras(),selected:'EX-2101',job:jobs[0]!.id,draft:emptyDraft(),errors:{},query:'',filter:'all',message:'',storage:'Design changes stay in this tab.',dialog:null,dialogText:'',amount:'',screen:'v001',stateIndex:0,navigationOpen:false,quoteSent:false,quoteNote:'Replace kitchen cabinets and worktop; retain appliances.',finalLocked:false,finalCompleted:false,catalogueGroup:0};
  componentDidMount(){try{const raw=sessionStorage.getItem(STORAGE);const saved=restoreDesign(raw);if(saved)this.setState({extras:saved});else if(raw)this.setState({storage:'The saved design example could not be read. Original fictional data is shown.'});}catch{this.setState({storage:'Browser storage unavailable. Design changes last until reload only.'});}this.readHash();window.addEventListener('hashchange',this.readHash);}
  componentWillUnmount(){window.removeEventListener('hashchange',this.readHash);}
  readHash=()=>{const p=new URLSearchParams(window.location.hash.slice(1));const persona=p.get('person') as Persona;const page=p.get('view') as Page;const screen=p.get('screen');if(personas.some(v=>v.id===persona)&&Object.prototype.hasOwnProperty.call(pageTitles,page))this.setState({persona,page:page==='screen'&&(!screen||!screens.some(s=>s.id===screen))?'catalogue':page,screen:screen??'v001',selected:p.get('extra')??this.state.selected,mode:'design',query:'',filter:page==='review'?'mine':'all'});};
  navigate=(page:Page,options:Partial<Pick<State,'selected'|'job'|'screen'>>={})=>{if(this.state.page==='capture'&&(this.state.draft.description||this.state.draft.note)&&page!=='capture'&&!window.confirm('Leave this unsaved design record?'))return;const next={...this.state,...options,page};this.setState(previous=>({...previous,...options,page,query:'',filter:page==='review'?'mine':'all',message:'',navigationOpen:false}));const h=new URLSearchParams({view:page,person:next.persona});if(page==='detail')h.set('extra',next.selected);if(page==='screen')h.set('screen',next.screen);window.history.pushState(null,'',`#${h}`);window.setTimeout(()=>document.querySelector<HTMLElement>('.jg-heading h1')?.focus(),0);};
  choosePersona=(persona:Persona)=>{if(this.state.page==='capture'&&(this.state.draft.description||this.state.draft.note)&&!window.confirm('Discard this unsaved design record and switch fictional role?'))return;const page:Page=persona==='client'?'review':'today';this.setState({persona,page,draft:emptyDraft(),query:'',filter:page==='review'?'mine':'all',message:'',dialog:null});window.history.pushState(null,'',`#view=${page}&person=${persona}`);};
  save=(extras:Extra[],message:string,after:Partial<State>={})=>{let storage='Saved in this browser tab only. No JobGuard server record.';try{sessionStorage.setItem(STORAGE,JSON.stringify(extras));}catch{storage='Not saved to browser storage. This design change will be lost on reload.';}this.setState(previous=>({...previous,extras,message,storage,...after}));};
  submitDraft=()=>{const errors=validateDraft(this.state.draft);if(Object.keys(errors).length){this.setState({errors});return;}const id=`EX-${Date.now().toString(36).toUpperCase()}`;const extra=createDesignExtra(this.state.draft,id);this.save([extra,...this.state.extras],'Fictional extra recorded. It needs pricing; it is not approved, billed or paid.',{page:'detail',selected:id,draft:emptyDraft(),errors:{}});window.history.replaceState(null,'',`#view=detail&person=operative&extra=${id}`);};
  updateDraft=(patch:Partial<Draft>)=>{this.setState(s=>({draft:{...s.draft,...patch,...(('description'in patch||'note'in patch||'job'in patch)?{photo:false,resident:false}:{})},errors:{}}));};
  perform=(action:DesignAction,extra:Extra,detail='')=>{try{const current=this.state.extras.find(x=>x.id===extra.id);if(!current)throw new Error('This record is no longer available.');const updated=transition(current,action,this.state.persona,extra.revision,detail);this.save(this.state.extras.map(x=>x.id===updated.id?updated:x),`${statusLabels[updated.state]}. Design change only.`,{dialog:null,dialogText:'',amount:''});}catch(e){this.setState({message:e instanceof Error?e.message:'The design action could not be applied.'});}};
  openExtra=(extra:Extra)=>this.navigate('detail',{selected:extra.id});
  renderRows(items:Extra[],compact=false){return items.length?<div className={`jg-extra-list ${compact?'jg-compact':''}`}>{items.map(e=><button key={e.id} className="jg-extra-row" onClick={()=>this.openExtra(e)}><span className="jg-row-symbol"><Icon name={e.state==='approved'?'check':'file'}/></span><span className="jg-row-main"><small>{e.job} <span>·</span> {e.id}</small><strong>{e.description}</strong><span className="jg-row-meta"><Badge tone={toneFor(e)}>{statusLabels[e.state]}</Badge><span>Revision {e.revision}</span></span></span><span className="jg-row-end"><Money pence={e.pence}/><Icon name="chevron"/></span></button>)}</div>:<Empty title="Nothing in this view" description="Change the filters or choose another fictional scenario." icon="search"/>;}
  renderToday(){const {persona,extras}=this.state;if(persona==='builder')return this.renderBuilderHome();if(persona==='client')return this.renderReview();const me=personas.find(p=>p.id===persona)!;const pending=extras.filter(e=>attentionFor(persona,e));const approved=extras.filter(e=>e.state==='approved');return <><Heading eyebrow="NORTHSIDE PROPERTY SERVICES · FICTIONAL WORKSPACE" title={`Good morning, ${me.name.split(' ')[0]}.`} description={persona==='operative'?'Your jobs, your extras. Nothing gets lost between site and office.':'See what needs a decision. Keep work and money moving.'} action={persona==='operative'?<Button tone="primary" icon="plus" onClick={()=>this.navigate('capture')}>Log an extra</Button>:<Button tone="primary" icon="check" onClick={()=>this.navigate('review')}>Open review queue</Button>}/><div className="jg-metrics"><Metric label={persona==='operative'?'Assigned work orders':'Active work orders'} value={String(jobs.length)} detail="Fictional schedule for this preview" icon="jobs"/><Metric label="Needs your attention" value={String(pending.length)} detail="Only the selected role’s next actions" icon="clock"/><Metric label="Approved extras" value={pounds(totalPence(approved))} detail="Illustrative net · not billed or paid"/><Metric label="Unpriced records" value={String(extras.filter(e=>e.pence===null).length)} detail="No invented price or recovered value" icon="file"/></div><div className="jg-content-grid"><div><Card title={persona==='operative'?'Your work today':'Work in progress'} subtitle="Open a work order before recording additional work." action={<Button tone="quiet" onClick={()=>this.navigate('jobs')}>View all</Button>}><div className="jg-job-list">{jobs.slice(0,2).map((j,i)=><button className="jg-job-card" key={j.id} onClick={()=>this.navigate('job',{job:j.id})}><div className={`jg-building jg-building-${i}`}><Icon name="home"/></div><div><small>{j.id} · {j.client}</small><h3>{j.name}</h3><p>{j.site}</p><div className="jg-job-progress"><span style={{width:`${j.progress}%`}}/></div><small>{j.tag}</small></div><Icon name="chevron"/></button>)}</div></Card><Card title={persona==='operative'?'Your latest extras':'Decisions awaiting your action'} subtitle={persona==='operative'?'Track each record without chasing the office.':'Waiting on someone else is kept out of this queue.'} action={<Button tone="quiet" onClick={()=>this.navigate(persona==='operative'?'extras':'review')}>View all</Button>}>{this.renderRows(persona==='operative'?extras.slice(0,3):pending.slice(0,3),true)}</Card></div><div><section className="jg-feature"><span className="jg-feature-icon"><Icon name="shield"/></span><p className="jg-eyebrow">FROM THE JOB TO THE BILL</p><h2>The detail matters.<br/>Capture it once.</h2><p>Keep the work order, the extra and the evidence together. The right person makes the next decision.</p><Button tone="primary" icon="arrow" onClick={()=>this.navigate(persona==='operative'?'capture':'review')}>{persona==='operative'?'Record extra work':'Review extra work'}</Button></section><Card title="At a glance"><DescriptionList items={[["Waiting for supervisor",extras.filter(e=>e.state==='awaiting_supervisor').length],["Waiting for client",extras.filter(e=>e.state==='awaiting_client').length],["Billed and paid",'Not connected']]}/><div className="jg-card-pad"><p className="jg-micro">These are separate stages. An approval is not an invoice, payment or fee entitlement.</p></div></Card></div></div></>;}
  renderJobs(){if(this.state.persona==='builder')return <><Heading title="Your jobs" description="Owner-run work, without contractor administration."/><Card title="Active job"><button className="jg-extra-row" onClick={()=>this.navigate('today')}><Icon name="home"/><span className="jg-row-main"><small>B-1001 · Fictional customer</small><strong>Kitchen renovation</strong><span>Accepted quote, captured changes and evidence in one place</span></span><Icon name="chevron"/></button></Card></>;const filtered=jobs.filter(j=>`${j.id} ${j.name} ${j.client}`.toLowerCase().includes(this.state.query.toLowerCase()));return <><Heading title={this.state.persona==='operative'?'Your work orders':'Work-order register'} description="Instructions, revisions and additional work in one place."/><Card><div className="jg-toolbar"><Search label="Search work orders" value={this.state.query} onChange={query=>this.setState({query})} placeholder="Search work order, job or client"/><Badge>{filtered.length} work orders</Badge></div><div className="jg-table-wrap"><table><thead><tr><th>Work order</th><th>Client</th><th>Status</th><th>Revision</th><th><span className="jg-sr-only">Open</span></th></tr></thead><tbody>{filtered.map(j=><tr key={j.id}><td><button className="jg-text-link" onClick={()=>this.navigate('job',{job:j.id})}>{j.name}</button><small>{j.id} · {j.site}</small></td><td>{j.client}</td><td><Badge tone="blue">{j.tag}</Badge></td><td>1 · Example</td><td><Button tone="quiet" icon="chevron" aria-label={`Open ${j.id}`} onClick={()=>this.navigate('job',{job:j.id})}/></td></tr>)}</tbody></table>{!filtered.length&&<Empty title="No work orders found" description="Try a reference or a shorter search."/>}</div></Card></>;}
  renderJob(){const j=jobs.find(j=>j.id===this.state.job)??jobs[0]!;return <><Heading eyebrow={`${j.id} · ORDER REVISION 1 · FICTIONAL`} title={j.name} description={`${j.client} · ${j.site}`} action={this.state.persona==='operative'?<Button tone="primary" icon="plus" onClick={()=>{this.setState({draft:{...emptyDraft(),job:j.id}});this.navigate('capture');}}>Log an extra</Button>:undefined}/><div className="jg-content-grid"><div><Card title="What is included" subtitle="Check the instruction before recording additional work."><div className="jg-card-pad"><Badge tone="green">Current example revision</Badge><p className="jg-big-copy">{j.included}</p><DescriptionList items={[["Instruction source",'Fictional client work order'],['Quantity','As described in the example instruction'],['Work permission','Not established by this preview']]}/></div></Card><Card title="Extras on this work order" subtitle="A new record does not change the original instruction.">{this.renderRows(this.state.extras.filter(e=>e.job===j.id))}</Card></div><div><Card title="Visit and site context"><DescriptionList items={[["Assigned operative",'Alex Morgan · fictional'],['Resident details','Not included in this design dataset'],['Access and safety','Check your actual site instructions']]}/><div className="jg-card-pad"><Button onClick={()=>this.openSpec('Start visit')}>View visit design</Button></div></Card><Notice>Approval to bill extra work is not universal permission to start work. Follow the applicable site and client requirements.</Notice></div></div></>;}
  renderCapture(){const {draft,errors}=this.state;const j=jobs.find(x=>x.id===draft.job)!;return <><Heading eyebrow="SITE CAPTURE · FICTIONAL WORK ONLY" title="Log an extra" description="Say what changed. Keep the evidence with the work."/><div className="jg-capture-grid"><Card><form className="jg-form" onSubmit={e=>{e.preventDefault();this.submitDraft();}} noValidate><Progress steps={['The work','Evidence','Review']} current={draft.resident?2:draft.photo?1:0}/><label>Work order<select value={draft.job} onChange={e=>this.updateDraft({job:e.target.value})}>{jobs.map(j=><option key={j.id} value={j.id}>{j.id} · {j.name}</option>)}</select></label><div className="jg-inline-scope"><strong>Already instructed</strong><p>{j.included}</p></div><label>What is the extra work?<input autoComplete="off" maxLength={500} value={draft.description} aria-invalid={!!errors.description} aria-describedby={errors.description?'description-error':undefined} onChange={e=>this.updateDraft({description:e.target.value})} placeholder="For example, replace the damaged waste pipe"/></label>{errors.description&&<p id="description-error" className="jg-field-error">{errors.description}</p>}<label>Why is this outside the work order?<textarea maxLength={5000} rows={4} value={draft.note} aria-invalid={!!errors.note} onChange={e=>this.updateDraft({note:e.target.value})} placeholder="Explain what you found and how it differs from the instruction."/></label>{errors.note&&<p className="jg-field-error">{errors.note}</p>}<div className="jg-section-label"><h2>Evidence</h2><Badge tone={draft.photo?'blue':'neutral'}>{draft.photo?'Example attached':'Required in this scenario'}</Badge></div>{draft.photo?<Evidence description={draft.description} acknowledged={draft.resident}/>:<button type="button" className="jg-upload" onClick={()=>this.updateDraft({photo:true,resident:false})}><Icon name="camera"/><strong>Attach fictional evidence</strong><span>Use the built-in illustration. No camera or photo is uploaded.</span></button>}{errors.photo&&<p className="jg-field-error">{errors.photo}</p>}<label className="jg-checkbox"><input type="checkbox" checked={draft.resident} disabled={!draft.photo} onChange={e=>this.updateDraft({resident:e.target.checked})}/><span>I have reviewed the fictional description and evidence acknowledgement.<small>This rehearses an acknowledgement on the operative’s device. It is not paying-client approval.</small></span></label>{errors.resident&&<p className="jg-field-error">{errors.resident}</p>}<div className="jg-form-footer"><span>No price is required from the site operative.</span><Button tone="primary" type="submit" icon="plus">Record fictional extra</Button></div></form></Card><div><Card title="What happens next?"><div className="jg-card-pad"><ol className="jg-timeline"><li><strong>You record the work</strong><p>Keep the description and evidence together.</p></li><li><strong>A surveyor reviews the price</strong><p>An unpriced record stays unpriced.</p></li><li><strong>The right people approve</strong><p>Supervisor and client approval are separate.</p></li></ol></div></Card><Notice>Editing the work after adding evidence clears this example’s acknowledgement. Review the new wording again.</Notice></div></div></>;}
  renderReview(){const {extras,persona,query,filter}=this.state;const external=persona==='client';const scope=external?extras.filter(e=>jobs.find(j=>j.id===e.job)?.client==='Northside Homes'&&['awaiting_client','approved','rejected'].includes(e.state)):extras;const mine=scope.filter(e=>attentionFor(persona,e));const list=filter==='waiting'?scope.filter(e=>!attentionFor(persona,e)&&!['approved','rejected','withdrawn'].includes(e.state)):filter==='all'?scope:mine;return <><Heading eyebrow={external?'NORTHSIDE HOMES · FICTIONAL INVITED CLIENT':'NORTHSIDE PROPERTY SERVICES'} title={external?'Your approval requests':'Make the next decision.'} description={external?'Only the example requests shared with this fictional client appear here.':'The evidence, price and exact revision are ready for your review.'}/><Card><div className="jg-toolbar"><div className="jg-tabs" aria-label="Review filters">{(external?([['mine','Awaiting your decision'],['all','All example requests']] as const):([['mine','Needs my action'],['waiting','Waiting on others'],['all','All in scope']] as const)).map(([value,label])=><button key={value} className={(filter==='all'?value==='all':filter==='waiting'?value==='waiting':value==='mine')?'active':''} onClick={()=>this.setState({filter:value})}>{label}{value==='mine'&&<span>{mine.length}</span>}</button>)}</div><Search label="Search extras" value={query} onChange={query=>this.setState({query})} placeholder="Search description or reference"/></div>{this.renderRows(showRows(list,query,'all'))}</Card>{external&&<p className="jg-micro">This client view has no internal billing, fee statement, people-management or unrelated job navigation.</p>}</>;}
  renderExtras(){return <><Heading title="My extras" description="See the next stage, not just a submitted tick." action={<Button tone="primary" icon="plus" onClick={()=>this.navigate('capture')}>Log an extra</Button>}/><Card><div className="jg-toolbar"><Search label="Search my extras" value={this.state.query} onChange={query=>this.setState({query})} placeholder="Search extra or work order"/><label className="jg-select-label">Status<select value={this.state.filter} onChange={e=>this.setState({filter:e.target.value})}><option value="all">All statuses</option>{Object.entries(statusLabels).map(([v,label])=><option value={v} key={v}>{label}</option>)}</select></label></div>{this.renderRows(showRows(this.state.extras,this.state.query,this.state.filter))}</Card></>;}
  renderDetail(){const {persona,amount,dialogText}=this.state;const e=this.state.extras.find(x=>x.id===this.state.selected);if(!e)return <Empty title="Example record not found" description="The design may have been reset." action={<Button onClick={()=>this.navigate('extras')}>Back to extras</Button>}/>;const external=persona==='client';if(external&&(jobs.find(j=>j.id===e.job)?.client!=='Northside Homes'||!['awaiting_client','approved','rejected'].includes(e.state)))return <Empty title="No request shared with this client" description="Switch the fictional scenario in the design controls to explore another role."/>;const index=['logged','priced','awaiting_supervisor','awaiting_client','approved'].indexOf(e.state);return <><Heading eyebrow={`${e.job} / ${e.id} · REVISION ${e.revision}`} title={e.description} description={external?'Review this exact work and price before deciding.':'Everything behind this extra, in one place.'}/><div className="jg-detail-grid"><div><Card title="The work" action={<Badge tone={toneFor(e)}>{statusLabels[e.state]}</Badge>}><div className="jg-card-pad"><p className="jg-big-copy">{e.note}</p><DescriptionList items={[["Work order",e.job],['Origin','Site record · fictional, not editable'],['Price',<Money key="price" pence={e.pence}/>],['Commercial status',e.state==='approved'?'Approved in this design · not billed or paid':'Not yet approved for billing']]}/></div></Card><Card title="Evidence and acknowledgement"><Evidence description={e.description} acknowledged={e.resident}/></Card><Card title="Record history" subtitle="Earlier decisions remain visible when the record changes."><div className="jg-card-pad"><ol className="jg-timeline">{e.history.map((h,i)=><li key={`${i}-${h}`}><strong>{h}</strong><p>Design event {i+1} · not a server audit record</p></li>)}</ol></div></Card></div><div><Card title={attentionFor(persona,e)?'Your next action':'Current progress'}><div className="jg-card-pad"><Progress steps={['Capture','Price','Supervisor','Client','Approved']} current={Math.max(0,index)}/>{persona==='surveyor'&&e.state==='logged'&&<div className="jg-form"><label>Illustrative net price (£)<input inputMode="decimal" value={amount} onChange={v=>this.setState({amount:v.target.value})} placeholder="185.50"/></label><p className="jg-micro">Design-only free-text price. The practice-service screen uses the server’s schedule of rates.</p><Button tone="primary" onClick={()=>this.perform('price',e,amount)}>Save fictional price</Button></div>}{persona==='supervisor'&&e.state==='priced'&&<Button tone="primary" onClick={()=>this.perform('submit',e)}>Submit for supervisor review</Button>}{((persona==='supervisor'&&e.state==='awaiting_supervisor')||(persona==='client'&&e.state==='awaiting_client'))&&<div className="jg-stack"><p>You are deciding on <strong>revision {e.revision}</strong>, <Money pence={e.pence}/>. Changes require a new review.</p><Button tone="primary" icon="check" onClick={()=>this.setState({dialog:{kind:'approve',extra:{...e}},dialogText:'',message:''})}>Approve this revision</Button><Button tone="danger" onClick={()=>this.setState({dialog:{kind:'reject',extra:{...e}},dialogText:'',message:''})}>Reject with a reason</Button></div>}{persona==='operative'&&e.state==='logged'&&<Button onClick={()=>this.setState({dialog:{kind:'withdraw',extra:{...e}},dialogText:'',message:''})}>Withdraw this record</Button>}{persona==='operative'&&['rejected','withdrawn'].includes(e.state)&&<><label className="jg-form">Revised explanation<textarea value={dialogText} onChange={v=>this.setState({dialogText:v.target.value})}/></label><Button onClick={()=>this.setState({dialog:{kind:'revise',extra:{...e}}})}>Review revised example</Button></>}{!attentionFor(persona,e)&&e.state!=='approved'&&<p className="jg-muted">The selected fictional role has no approval action at this stage.</p>}{e.state==='approved'&&<Notice tone="success">Approval recorded in the design example. Nothing has been billed, sent or paid.</Notice>}</div></Card><p className="jg-micro">Fictional role switching is a prototype control, not a permission grant. Server-backed records are never handled by this simulator.</p></div></div></>;}
  renderPossible(){return <><Heading eyebrow="CONTRACTOR REVIEW · EXAMPLE FINDINGS" title="Possible extras" description="A prompt to look closer. Never an automatic approval or a claim of money earned."/><Notice>This is a prepared design scenario, not a running detection service. The small-builder Final Check is a separate experience.</Notice><div className="jg-content-grid"><Card title="Waste pipe work mentioned in a visit note" action={<Badge tone="amber">Needs a person to check</Badge>}><div className="jg-card-pad"><p className="jg-big-copy">“Existing waste pipe was damaged when the tap was removed.”</p><DescriptionList items={[["Source",'Fictional visit note · WO-1042'],['Order instruction',jobs[0]!.included],['Possible match','EX-2101 is already captured — do not bill twice']]}/><div className="jg-actions"><Button tone="primary" onClick={()=>this.navigate('detail',{selected:'EX-2101'})}>Compare captured record</Button><Button onClick={()=>this.setState({message:'Dismissal interaction rehearsed. No server finding or commercial record was changed.'})}>Dismiss example</Button></div></div></Card><Card title="What the reviewer checks"><div className="jg-card-pad"><ol className="jg-timeline"><li><strong>Is it already instructed?</strong><p>Compare scope and quantities, not only the words.</p></li><li><strong>Has someone captured it?</strong><p>Link to the canonical record; keep origin intact.</p></li><li><strong>Is there enough evidence?</strong><p>A suggestion is not a variation, debt or fee.</p></li></ol></div></Card></div></>;}
  renderBilling(){const approved=this.state.extras.filter(e=>e.state==='approved');return <><Heading eyebrow="COMMERCIAL OFFICE · DESIGN PREVIEW" title="Ready for billing" description="Approved work, with the evidence behind every line."/><div className="jg-metrics jg-three"><Metric label="Approved, not billed" value={pounds(totalPence(approved))} detail="Illustrative net value from these examples"/><Metric label="Exported" value="Not connected" detail="No export batch has been created" icon="download"/><Metric label="Paid" value="Not connected" detail="No settlement feed or verified payment" icon="check"/></div><Card title="Review the proposed export" subtitle="No real document, delivery or invoice is created by this screen.">{this.renderRows(approved)}<div className="jg-card-pad"><Button tone="primary" icon="file" onClick={()=>this.openSpec('Export preview')}>Explore export layout</Button></div></Card><Notice>Billing export and reconciliation still require the existing backend implementation and its checks. Approved is not billed; billed is not paid.</Notice></>;}
  renderStatements(){return <><Heading eyebrow="CONTRACTOR ACCOUNT · DESIGN PREVIEW" title="Statements" description="See where each amount comes from before you approve anything."/><Card title="No qualifying statement is connected"><Empty title="Keep the money trail intact" description="Origin → approval → invoice → allocation → payment. A statement cannot be inferred from the approval examples." icon="money" action={<Button tone="primary" onClick={()=>this.openSpec('Monthly statement')}>Explore statement design</Button>}/></Card><div className="jg-two"><Card title="Review a statement"><div className="jg-card-pad"><p>Inspect the exact period, statement revision and supporting lines. A dispute must not rewrite the original.</p><Button onClick={()=>this.openSpec('Statement approval or dispute')}>Open review design</Button></div></Card><Card title="Trace a payment"><div className="jg-card-pad"><p>See partial allocations, unmatched receipts and reversals as separate facts.</p><Button onClick={()=>this.openSpec('Partial payment and allocations')}>Open allocation design</Button></div></Card></div></>;}
  renderReports(){const stages=[['logged','Needs pricing'],['priced','Priced'],['awaiting_supervisor','Supervisor review'],['awaiting_client','Client review'],['approved','Approved · not billed']] as const;return <><Heading eyebrow="FICTIONAL DATA · NOT A COMMERCIAL PERFORMANCE CLAIM" title="A clear view of the pipeline" description="Separate captured, approved, billed and paid. No double-counted benefit."/><Card title="Current example records"><div className="jg-report">{stages.map(([state,label])=>{const records=this.state.extras.filter(e=>e.state===state);return <div className="jg-report-row" key={state}><strong>{label}</strong><div><span style={{width:`${records.length/Math.max(1,this.state.extras.length)*100}%`}}/></div><span>{records.length} records</span><Money pence={records.length?totalPence(records):0}/></div>;})}</div><div className="jg-card-pad"><p className="jg-micro">Unpriced records carry no amount. These are current-stage totals, not cumulative funnel conversions or money recovered.</p></div></Card><div className="jg-two"><Card title="Pilot baseline"><div className="jg-card-pad"><p>A baseline needs a defined period, versioned method and comparable jobs. This preview has no measured results.</p><Button onClick={()=>this.openSpec('Pilot baseline comparison')}>Explore comparison design</Button></div></Card><Card title="What is still unknown"><DescriptionList items={[["Actual billed value",'Not connected'],['Verified paid value','Not connected'],['Causal improvement','Not established']]}/></Card></div></>;}
  renderSetup(){return <><Heading title="Workspace setup" description="Keep configuration out of the operative’s way."/><div className="jg-spec-grid">{[['People and access','users'],['Client contract and versions','file'],['Approval rule setup and preview','check'],['Schedule of rates and versions','money'],['System connections','layers'],['Audit and security evidence','shield']].map(([title,icon])=><button className="jg-spec-card" key={title} onClick={()=>this.openSpec(title!)}><Icon name={icon as IconName}/><h2>{title}</h2><p>Explore the proposed layout. No permission or configuration changes are made.</p><span>Open design <Icon name="arrow"/></span></button>)}</div></>;}
  renderBuilderHome(){return <><Heading eyebrow="MORGAN REED · FICTIONAL OWNER-RUN BUSINESS" title="Keep the job together." description="Your quote, your captured changes and the next decision — without the office complexity." action={<Button tone="primary" onClick={()=>this.navigate('quotes')} icon="plus">Open quote</Button>}/><div className="jg-metrics jg-three"><Metric label="Active example jobs" value="1" detail="Kitchen renovation · B-1001" icon="jobs"/><Metric label="Quote" value={this.state.quoteSent?'Simulated send':'Draft'} detail="No customer message has been sent" icon="file"/><Metric label="Final account" value={this.state.finalLocked?'Example locked':'Not complete'} detail="No hidden finding count is shown" icon="shield"/></div><div className="jg-content-grid"><Card title="Kitchen renovation" subtitle="B-1001 · fictional customer"><div className="jg-card-pad"><p className="jg-big-copy">{this.state.quoteNote}</p><DescriptionList items={[["Accepted baseline",'Illustrative record only'],['Builder-captured work','Always kept separate from JobGuard findings'],['Next step','Review work and captured changes']]}/><div className="jg-actions"><Button onClick={()=>this.navigate('quotes')}>Quote and scope</Button><Button onClick={()=>this.navigate('supplies')}>Supplies</Button><Button onClick={()=>this.navigate('final')}>Final account</Button></div></div></Card><Card title="Your working record"><div className="jg-card-pad"><p>Keep notes, photos, messages and explicitly captured changes with the job.</p><Button onClick={()=>this.openSpec('Diary and customer messages')}>Explore diary design</Button><p className="jg-micro">No contractor watchdog findings appear in this small-builder view.</p></div></Card></div></>;}
  renderQuotes(){return <><Heading eyebrow="SMALL-BUILDER DESIGN PREVIEW" title="Kitchen renovation quote" description="Review the work and the exact customer-facing document."/><div className="jg-content-grid"><Card title="The proposed work" action={<Badge tone="blue">{this.state.quoteSent?'Simulated send':'Draft example'}</Badge>}><div className="jg-form"><label>Scope notes<textarea rows={4} value={this.state.quoteNote} onChange={e=>this.setState({quoteNote:e.target.value,quoteSent:false})} maxLength={5000}/></label><DescriptionList items={[["Customer",'Fictional customer'],['Recipient','customer@example.invalid'],['Document','Illustrative draft · not a commercial quote'],['Tax basis','Not determined in this design example']]}/><Button tone="primary" icon="file" onClick={()=>{this.setState({quoteSent:true,message:'Quote-send interaction simulated. No document was issued and no message was sent.'});}}>Simulate quote send</Button></div></Card><Card title="Before a real send"><div className="jg-card-pad"><p>Confirm the scope, quantities, prices, supported tax basis and exact recipient. Customer acceptance is a separate event.</p><Button onClick={()=>this.openSpec('Quote pricing')}>Explore pricing design</Button><Button onClick={()=>this.openSpec('Quote response and acceptance')}>Explore acceptance design</Button></div></Card></div></>;}
  renderSupplies(){return <><Heading eyebrow="SMALL-BUILDER DESIGN PREVIEW" title="Supplies, without the loose ends." description="Check the order, what arrived and the supplier’s bill side by side."/><Card title="A discrepancy to review" action={<Badge tone="amber">Prepared example</Badge>}><div className="jg-table-wrap"><table><thead><tr><th>Example item</th><th>Ordered</th><th>Received</th><th>Invoiced</th><th>What to check</th></tr></thead><tbody><tr><td>Cabinet handles · each</td><td>12</td><td>10</td><td>12</td><td>Two not yet delivered</td></tr><tr><td>Worktop sealant · cartridge</td><td>3</td><td>3</td><td>4</td><td>Check the invoice quantity</td></tr></tbody></table></div><div className="jg-card-pad"><Button tone="primary" onClick={()=>this.openSpec('Order–delivery–invoice match')}>Review matching design</Button><p className="jg-micro">The difference is not a verified overcharge or a cash recovery. No supplier has been contacted.</p></div></Card></>;}
  renderMoney(){return <><Heading title="Your money" description="Customer invoices and JobGuard account bills are different books."/><div className="jg-two"><Card title="Customer invoices"><Empty title="No connected invoice data" description="Explore the proposed invoice, partial payment and credit-note screens using labelled examples." icon="file" action={<Button onClick={()=>this.openSpec('Customer invoice and payment record')}>Open invoice design</Button>}/></Card><Card title="JobGuard account"><Empty title="No fees or subscription charged" description="This design preview creates no payment authority, mandate or fee entitlement." icon="shield" action={<Button onClick={()=>this.openSpec('JobGuard account bills')}>Open account design</Button>}/></Card></div><Button tone="primary" onClick={()=>this.navigate('final')}>Review the final account</Button></>;}
  renderFinal(){const {finalLocked,finalCompleted}=this.state;return <><Heading eyebrow="SMALL-BUILDER DESIGN PREVIEW · B-1001" title="Complete the final account" description="Check your own work and captured changes before the Final Check."/>{!finalLocked?<Card title="Your account comes first"><div className="jg-card-pad"><p className="jg-big-copy">Review the accepted scope, every captured change and any final additions. Completing the work is different from locking its final account.</p><DescriptionList items={[["Accepted scope",'Kitchen renovation · fictional'],['Captured changes','Review your own register first'],['Final additions','Add your own work before the lock']]}/><Button tone="primary" onClick={()=>this.setState({finalLocked:true,finalCompleted:false,message:'The locked-account scenario is now selected. No real account was locked.'})}>Explore the locked-account scenario</Button></div></Card>:<Card title={finalCompleted?'Completed Final Check example':'Final Check: no result established'}><div className="jg-card-pad">{!finalCompleted?<><Notice>Processing status is not connected. This screen must not imply that there are zero findings.</Notice><Button onClick={()=>this.setState({finalCompleted:true})}>Show a prepared completed example</Button></>:<><Badge tone="amber">Illustrative finding · not a debt</Badge><h3>Additional boxing-in described in a job note</h3><p>Compare the source with the accepted scope and your captured-change register. Confirmation would use the normal variation path.</p><Button onClick={()=>this.openSpec('Review a possible missing item')}>Explore finding review</Button></>}<p className="jg-micro">No finding count is rendered before selecting the locked-account scenario. These controls do not invoke a detector or change an actual account.</p></div></Card>}</>;}
  openSpec=(title:string)=>{const target=screens.find(s=>s.title===title)??screens.find(s=>s.title.toLowerCase().includes(title.toLowerCase()));if(target)this.navigate('screen',{screen:target.id});else this.navigate('catalogue');};
  renderCatalogue(){const {query,catalogueGroup}=this.state;const found=screens.filter(s=>(!catalogueGroup||s.group===catalogueGroup)&&`${s.title} ${s.purpose} ${s.source} ${groups.find(g=>g.id===s.group)?.name??''}`.toLowerCase().includes(query.toLowerCase()));return <><Heading eyebrow="DESIGN WORKBENCH · NOT PRODUCT NAVIGATION" title="The whole product, mapped." description={`${screens.length} named views across ${groups.length} areas. Core journeys have interactive screens; remaining views are labelled layout specimens.`} action={<Button icon="layers" onClick={()=>this.navigate('states')}>15 interface states</Button>}/><div className="jg-toolbar jg-catalogue-toolbar"><Search label="Search screen catalogue" value={query} onChange={query=>this.setState({query})} placeholder="Find a screen, capability or source reference"/><label className="jg-select-label">Area<select value={catalogueGroup} onChange={e=>this.setState({catalogueGroup:Number(e.target.value)})}><option value={0}>All areas</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><Badge>{found.length} views</Badge></div><div className="jg-spec-grid">{found.map(s=><button data-testid="screen-card" key={s.id} className="jg-spec-card" onClick={()=>this.navigate('screen',{screen:s.id})}><small>{String(s.group).padStart(2,'0')} / {s.id.toUpperCase()}</small><h2>{s.title}</h2><p>{s.purpose}</p><span>Explore layout <Icon name="arrow"/></span></button>)}</div>{!found.length&&<Empty title="No matching screen" description="Try a shorter search or another area."/>}</>;}
  renderSpec(){const s=screens.find(s=>s.id===this.state.screen)??screens[0]!;const group=groups.find(g=>g.id===s.group)!;const dedicated:Record<string,Page>={'Today / assigned jobs':'today','Work-order detail':'job','Log an extra: words route':'capture','Evidence capture and review':'capture','Review and submit':'capture','Review inbox':'review','Extra review detail':'detail','My extras':'extras','Possible extras inbox':'possible','Commercial overview':'today','Ready for billing':'billing','Work-order register':'jobs','Operational reports':'reports','My business home':'today','Quotes register':'quotes','Start a quote from notes':'quotes','Quote preview and send':'quotes','Order–delivery–invoice match':'supplies','Final-account preparation':'final','Complete final account':'final','Customer invoice and payment record':'money'};const linked=dedicated[s.title];const related=group.views.filter(x=>x.id!==s.id);return <><Heading eyebrow={`${s.id.toUpperCase()} · ${group.name}`} title={s.title} description={s.purpose} action={<Button icon="grid" onClick={()=>this.navigate('catalogue')}>All screens</Button>}/><Notice>This is a layout specimen from the proposed screen map, not a completed backend feature. Fields and actions below demonstrate structure only.</Notice><div className="jg-content-grid"><Card title="Proposed workspace" action={<Badge tone="blue">Layout specimen</Badge>}><div className="jg-card-pad">{this.renderSpecBody(s)}{linked&&<Button tone="primary" icon="arrow" onClick={()=>{const p:Persona=s.group>=7&&s.group<=10?'builder':s.group===4?'client':s.group===2?'operative':s.group===3?'supervisor':'finance';this.setState({persona:p},()=>this.navigate(linked));}}>Open interactive companion</Button>}</div></Card><div><Card title="Source and boundaries"><div className="jg-card-pad"><p className="jg-eyebrow">PRODUCT SCOPE REFERENCE</p><p>{s.source}</p><p className="jg-micro">Source: JobGuard complete proposed screen map, version 1, 15 October 2026. A capability in the plan is not evidence of implementation.</p><Badge>Not connected</Badge></div></Card><Card title="Continue this journey"><div className="jg-related">{related.slice(0,5).map(x=><button key={x.id} onClick={()=>this.navigate('screen',{screen:x.id})}>{x.title}<Icon name="chevron"/></button>)}</div></Card></div></div></>;}
  renderSpecBody(s:Screen){if(s.group===1||s.group===6||s.group===14)return <div className="jg-form"><label>{s.group===1?'Example workspace':'Configuration name'}<input defaultValue="Northside · fictional workspace" key={s.id} readOnly/></label><DescriptionList items={[["Access",'Only the appropriate server-granted role'],['Version','Example configuration · no changes saved'],['Outcome','No invitation, export or access change made']]}/><Button disabled>Server-backed action not connected</Button></div>;if(s.group===4||s.group===11)return <><div className="jg-document"><p className="jg-eyebrow">YOUR REQUEST · FICTIONAL EXAMPLE</p><h3>Review the exact work</h3><p>Replace damaged waste pipe beneath the kitchen sink.</p><DescriptionList items={[["Request",'Example revision 1'],['Amount','Shown only from the exact approved request'],['Decision','No decision recorded by this specimen']]}/></div><Button disabled>Exact request connection required</Button></>;if(s.group===12)return <><Empty title="Native device behaviour is not implemented here" description="Queued, uploaded, accepted and rejected are separate states. A phone-sized browser view does not prove native offline storage or synchronisation." icon="shield"/><Badge tone="amber">Device-testing gate remains</Badge></>;if(s.group===5||s.group===9||s.group===10||s.group===13)return <><div className="jg-mini-flow">{['Source record','Exact revision','Human decision','Recorded outcome'].map((t,i)=><div key={t}><small>0{i+1}</small><strong>{t}</strong></div>)}</div><DescriptionList items={[["Scenario",s.title],['Document / case','Fictional reference only'],['Amount or outcome','Unknown until supported by source facts'],['Unresolved items','Kept visible; never replaced by a successful-looking result']]}/><Button disabled>No financial or external action in this specimen</Button></>;if(s.group===8)return <><div className="jg-table-wrap"><table><thead><tr><th>Source line</th><th>Order</th><th>Received</th><th>Invoice</th></tr></thead><tbody><tr><td>Fictional item · each</td><td>12</td><td>10</td><td>12</td></tr></tbody></table></div><Notice>A quantity difference needs review. It is not automatically an overcharge or recovery.</Notice></>;return <><DescriptionList items={[["Work reference",'WO-1042 · fictional'],['Instructed work',jobs[0]!.included],['View purpose',s.purpose],['Record state','Illustrative only; not stored on the server']]}/><Evidence description="An example detail stays linked to the correct work record."/><Button disabled>Use the interactive companion where available</Button></>;}
  renderStates(){const state=states[this.state.stateIndex]!;const names=['Loading','Empty','No results','Validation error','Submitting','Outcome unknown','Saved','Permission changed','Stale revision','Rejected','Partial allocation','Offline','Evidence pending','Dispute','Unavailable'];const title=names[this.state.stateIndex]??'Interface state';return <><Heading eyebrow="REUSABLE STATE LIBRARY" title="Make every outcome clear." description="A saved tick is only one of the states the interface needs."/><div className="jg-states-grid"><Card title="Choose a state"><div className="jg-related">{names.map((name,i)=><button aria-pressed={i===this.state.stateIndex} className={i===this.state.stateIndex?'active':''} key={name} onClick={()=>this.setState({stateIndex:i})}>{String(i+1).padStart(2,'0')} · {name}<Icon name="chevron"/></button>)}</div></Card><Card title={title}><div className="jg-card-pad"><Badge tone={[3,5,7,8,14].includes(this.state.stateIndex)?'amber':'blue'}>Deliberately selected example</Badge>{this.state.stateIndex===0?<div className="jg-skeleton" aria-label="Loading illustration"><div/><div/><div/></div>:this.state.stateIndex===5?<Notice tone="error"><strong>We could not confirm the outcome.</strong><p>Do not repeat the action. Inspect the stored request and reconcile it before trying again.</p></Notice>:<Empty title={title==='Saved'?'Saved to the example record':title} description={state.description} icon={title==='Saved'?'check':'alert'}/>}<p className="jg-micro">This library does not change a business record. These are deliberately chosen design states, not a response to an actual request.</p></div></Card></div></>;}
  renderHelp(){return <><Heading title="Try the journey" description="Use only fictional work in this preview."/><Card title="From site to client"><div className="jg-card-pad"><ol className="jg-timeline"><li><strong>Site operative</strong><p>Open a job, record an extra and attach the built-in evidence illustration.</p></li><li><strong>Surveyor</strong><p>Switch fictional role in the design controls. Review the new extra and enter an illustrative price.</p></li><li><strong>Supervisor</strong><p>Submit and approve the exact revision, or reject it with a reason.</p></li><li><strong>Invited client</strong><p>Approve the shared example request. It remains not billed and not paid.</p></li></ol><Notice>For server-backed practice, open the separate Practice service mode. It never converts a failed request into a fictional success.</Notice><p className="jg-micro">No support address has been invented. Contact the person who shared this preview with you.</p></div></Card></>;}
  renderContent(){if(this.state.persona==='builder'&&!['today','jobs','quotes','supplies','money','final','catalogue','screen','states','help'].includes(this.state.page))return <Empty title="This is not part of the small-builder workspace" description="Use your job, quote, money or final-account view. Contractor findings are a separate track."/>;if(this.state.persona==='client'&&!['review','detail','catalogue','screen','states','help'].includes(this.state.page))return <Empty title="This page is not shared with the client" description="Open your approval requests, or use the separate design workbench." action={<Button onClick={()=>this.navigate('review')}>My requests</Button>}/>;switch(this.state.page){case'today':return this.renderToday();case'jobs':return this.renderJobs();case'job':return this.renderJob();case'capture':return this.state.persona==='operative'?this.renderCapture():<Empty title="This capture route is for the fictional site operative" description="Choose the operative in design controls. This is not a permission grant."/>;case'extras':return this.renderExtras();case'review':return this.renderReview();case'detail':return this.renderDetail();case'possible':return this.renderPossible();case'billing':return this.renderBilling();case'statements':return this.renderStatements();case'reports':return this.renderReports();case'setup':return this.renderSetup();case'quotes':return this.renderQuotes();case'supplies':return this.renderSupplies();case'money':return this.renderMoney();case'final':return this.renderFinal();case'catalogue':return this.renderCatalogue();case'screen':return this.renderSpec();case'states':return this.renderStates();case'help':return this.renderHelp();}}
  render(){const s=this.state,person=personas.find(p=>p.id===s.persona)!;const nav=navFor(s.persona);if(s.mode==='practice')return <div className="jg-preview"><PracticeWorkspace {...(this.props.createPracticeClient?{createClient:this.props.createPracticeClient}:{})} onExit={()=>this.setState({mode:'design',message:'Returned to fictional design data. No practice record has been copied.'})}/></div>;return <div className={`jg-preview jg-design-shell ${s.persona==='operative'?'jg-field':''}`}><a href="#jg-main" className="jg-skip">Skip to content</a><div className="jg-demo-bar"><strong><span className="jg-status-dot"/> DESIGN PREVIEW</strong><span className="jg-demo-label">Fictional data. No real sends, bills or payments.</span><button onClick={()=>this.setState({mode:'practice',dialog:null})}>Practice service <Icon name="arrow"/></button></div><aside className={`jg-sidebar ${s.navigationOpen?'jg-sidebar-open':''}`}><button className="jg-brand" onClick={()=>this.navigate('today')} aria-label="JobGuard home"><span><Icon name="shield"/></span>JobGuard</button><div className="jg-workspace"><span className="jg-workspace-mark">{s.persona==='builder'?'MR':s.persona==='client'?'NH':'N'}</span><div><strong>{s.persona==='builder'?'Morgan Reed':s.persona==='client'?'Northside Homes':'Northside Property'}</strong><small>{s.persona==='builder'?'Small-builder workspace':s.persona==='client'?'Invited client view':'Contractor workspace'}</small></div></div><p className="jg-nav-label">WORKSPACE</p><nav aria-label="Workspace navigation">{nav.map(([page,icon,label])=><button key={page} className={s.page===page?'active':''} onClick={()=>this.navigate(page)}><Icon name={icon}/><span>{label}</span>{page==='review'&&<b>{s.extras.filter(e=>attentionFor(s.persona,e)&&(s.persona!=='client'||jobs.find(j=>j.id===e.job)?.client==='Northside Homes')).length}</b>}</button>)}</nav><div className="jg-sidebar-bottom"><p className="jg-nav-label">DESIGN WORKBENCH</p><button onClick={()=>this.navigate('catalogue')}><Icon name="grid"/>Screen catalogue <small>143</small></button><button onClick={()=>this.navigate('help')}><Icon name="file"/>Try the journey</button><div className="jg-person"><span>{person.initials}</span><div><strong>{person.name}</strong><small>{person.job} · fictional</small></div></div></div></aside><div className="jg-main-shell"><header className="jg-topbar"><button className="jg-mobile-menu" aria-label="Toggle navigation" onClick={()=>this.setState({navigationOpen:!s.navigationOpen})}><Icon name="grid"/></button><div className="jg-breadcrumb">{s.persona==='builder'?'My business':s.persona==='client'?'Client requests':'Workspace'}<Icon name="chevron"/><strong>{pageTitles[s.page]}</strong></div><div className="jg-topbar-right"><span className="jg-online"><i/>Design only</span><Button tone="quiet" icon="bell" aria-label="Open items requiring attention" onClick={()=>this.navigate(s.persona==='builder'?'quotes':'review')}/><span className="jg-avatar">{person.initials}</span></div></header><div className="jg-design-controls"><label>Explore as <select aria-label="Fictional role" value={s.persona} onChange={e=>this.choosePersona(e.target.value as Persona)}>{personas.map(p=><option key={p.id} value={p.id}>{p.job}</option>)}</select></label><span>{s.storage}</span><Button tone="quiet" icon="refresh" onClick={()=>this.setState({dialog:{kind:'reset'},dialogText:'',message:''})}>Reset example</Button></div><main id="jg-main" className="jg-main">{s.message&&<Notice>{s.message}</Notice>}{this.renderContent()}<footer className="jg-footer"><span>JobGuard · reusable web interface preview</span><span>Design examples are not server records.</span></footer></main></div><nav className="jg-mobile-nav" aria-label="Mobile navigation">{nav.slice(0,4).map(([page,icon,label])=><button key={page} className={s.page===page?'active':''} onClick={()=>this.navigate(page)}><Icon name={icon}/><span>{label}</span></button>)}{s.persona==='operative'&&<button className="jg-mobile-capture" onClick={()=>this.navigate('capture')}><Icon name="plus"/><span>Log extra</span></button>}</nav>{s.dialog&&<Modal title={s.dialog.kind==='reset'?'Reset this design example?':s.dialog.kind==='approve'?'Approve this exact revision?':s.dialog.kind==='revise'?'Rehearse the revised record?':'Record your reason'} onClose={()=>this.setState({dialog:null})}><div className="jg-form">{s.message&&<Notice tone="error">{s.message}</Notice>}{s.dialog.kind==='reset'?<p>This clears fictional extras in this tab only. It does not touch the practice service, jobs or financial records.</p>:<><p><strong>{s.dialog.extra?.description}</strong></p><p>Revision {s.dialog.extra?.revision} · <Money pence={s.dialog.extra?.pence??null}/></p>{s.dialog.kind==='approve'?<Notice>This records a fictional {s.persona} approval. No bill, payment or real approval is created.</Notice>:<label>{s.dialog.kind==='revise'?'Revised explanation':'Reason'}<textarea autoFocus rows={3} maxLength={5000} value={s.dialogText} onChange={e=>this.setState({dialogText:e.target.value})}/></label>}{s.dialog.kind==='revise'&&<label className="jg-checkbox"><input type="checkbox" required id="revise-ack"/><span>The fictional evidence and acknowledgement must be reviewed again for the changed wording.</span></label>}</>}<div className="jg-actions"><Button onClick={()=>this.setState({dialog:null})}>Cancel</Button><Button tone={s.dialog.kind==='reject'?'danger':'primary'} onClick={()=>{const d=s.dialog!;if(d.kind==='reset'){this.save(seedExtras(),'Original fictional example restored.',{dialog:null,draft:emptyDraft(),finalLocked:false,finalCompleted:false,quoteSent:false});}else if(d.extra){if(d.kind==='revise'&&!(document.getElementById('revise-ack') as HTMLInputElement|null)?.checked){this.setState({message:'Review the acknowledgement for the revised wording first.'});return;}this.perform(d.kind,d.extra,s.dialogText);}}}>{s.dialog.kind==='reset'?'Reset fictional data':s.dialog.kind==='approve'?'Confirm fictional approval':'Confirm design action'}</Button></div></div></Modal>}</div>;}
}
